CREATE TRIGGER UNDGSubstanceADR_Version_Create
	ON UNDGSubstanceADR
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ADR_PK, 'ADR'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstanceADR_Version_Update
	ON UNDGSubstanceADR
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ADR_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
